BEGIN;

-- ===== cm_94_2018 : قواعد وإجراءات التعامل على الأوراق المالية غير المقيدة =====
WITH ins_law_cm94 AS (
  INSERT INTO laws (law_no, law_year, title, short_title, category, kind, status, official_url, enacted_at, last_amended_at)
  VALUES (
    94, 2018,
    'قرار مجلس إدارة الهيئة رقم 94 لسنة 2018 بشأن قواعد وإجراءات التعامل على الأوراق المالية غير المقيدة بجداول البورصة المصرية وإجراءات نقل ملكيتها (نسخة محدثة حتى آخر تعديل بتاريخ 20/5/2026)',
    'قواعد التعامل على الأوراق المالية غير المقيدة بالبورصة',
    'capital_markets', 'board_decision', 'in_force',
    'https://fra.gov.eg/wp-content/uploads/2024/12/%D9%82%D8%B1%D8%A7%D8%B1-94-2018-%D9%82%D9%88%D8%A7%D8%B9%D8%AF-%D9%88%D8%A5%D8%AC%D8%B1%D8%A7%D8%A1%D8%A7%D8%AA-%D8%A7%D9%84%D8%AA%D8%B9%D8%A7%D9%85%D9%84-%D9%88%D9%81%D9%82%D8%A7%D9%8B-%D9%84%D8%A2%D8%AE%D8%B1-%D8%AA%D8%B9%D8%AF%D9%8A%D9%84-%D9%85%D8%A7%D9%8A%D9%88-2026.pdf',
    '2018-06-10', '2026-05-20'
  )
  ON CONFLICT (country_code, law_no, law_year) DO NOTHING
  RETURNING id
),
ins_art_cm94 AS (
  INSERT INTO articles (law_id, article_no, hierarchical_location, title, body)
  SELECT id, 1, NULL, 'قواعد التعامل على الأوراق المالية غير المقيدة بالبورصة', $cm94_2018$قرار مجلس إدارة الهيئة رقم (94) لسنة 2018 بتاريخ 2018/6/10
بشأن قواعد وإجراءات التعامل على الأوراق المالية غير المقيدة بجداول البورصة المصرية
وإجراءات نقل ملكيتها وفقاً لآخر تعديل بتاريخ 2026-5-20 (1)

مجلس إدارة الهيئة العامة للرقابة المالية

بعد الاطلاع على قانون شركات المساهمة وشركات التوصية بالأسهم والشركات ذات المسئولية المحدودة الصادر بالقانون رقم (159) لسنة 1981 ولائحته التنفيذية؛
وعلى قانون سوق رأس المال الصادر بالقانون رقم (95) لسنة 1992 ولائحته التنفيذية وتعديلاتهما والقرارات الصادرة تنفيذاً له؛
وعلى قانون الإيداع والقيد المركزي للأوراق المالية الصادر بالقانون رقم 93 لسنة 2000 ولائحته التنفيذية؛
وعلى القانون رقم (10) لسنة 2009 بتنظيم الرقابة على الأسواق والأدوات المالية غير المصرفية؛
وعلى قرار رئيس الجمهورية رقم (191) لسنة 2009 بالأحكام المنظمة لإدارة البورصة المصرية وشئونها المالية؛
وعلى النظام الأساسي للهيئة العامة للرقابة المالية الصادر بقرار رئيس الجمهورية رقم (192) لسنة 2009؛
وعلى قرار وزير الاقتصاد والتجارة الخارجية رقم (620) لسنة 2001؛
وعلى قرار مجلس إدارة الهيئة رقم (11) لسنة 2014 بشأن قواعد قيد وشطب الأوراق المالية بالبورصة المصرية وتعديلاته؛
وعلى قرار مجلس إدارة الهيئة رقم (17) لسنة 2017 بشأن التداول وإثبات نقل الملكية والإعلان عنها للأوراق المالية غير المقيدة بجداول البورصة المصرية؛
وعلى موافقة مجلس إدارة الهيئة بتاريخ 2018/6/10

قـــرر

(المادة الأولى)
يُعمل بالأحكام المرفقة بشأن قواعد وإجراءات التعامل على الأوراق المالية غير المقيدة بجداول البورصة المصرية، وإجراءات نقل ملكيتها.

(المادة الثانية)
تتولى البورصة إعداد وتجهيز النظم الآلية والمتطلبات الفنية اللازمة للتعامل على الأوراق المالية غير المقيدة بجداول البورصة المصرية.

(المادة الثالثة)
على البورصة إخطار الهيئة بأية مخالفات لعمليات التداول أو نقل الملكية للأوراق المالية غير المقيدة خلال يومي عمل من تاريخ اكتشاف المخالفة.

(المادة الرابعة)
يصدر مجلس إدارة البورصة المصرية الإجراءات التنفيذية لهذا القرار والنماذج والمستندات المرتبطة بعمليات التعامل على الأوراق المالية غير المقيدة بجداول البورصة المصرية وإجراءات نقل ملكيتها، ولا تسري هذه الإجراءات إلا بعد اعتمادها من رئيس الهيئة.

(المادة الخامسة)
يُلغى قرار مجلس إدارة الهيئة رقم (17) لسنة 2017 بشأن التداول وإثبات نقل الملكية والإعلان عنها للأوراق المالية غير المقيدة بجداول البورصة المصرية وتعديلاته، كما يُلغى كل حكم في أي قرار آخر يتعارض مع أحكام هذا القرار.

(المادة السادسة)
ينشر هذا القرار في الوقائع المصرية وعلى الموقع الالكتروني للهيئة والبورصة المصرية، ويعمل به اعتباراً من اليوم التالي لتاريخ نشره بالوقائع المصرية.

قواعد وإجراءات التعامل على الأوراق المالية غير المقيدة
بجداول البورصة المصرية وإجراءات نقل ملكيتها

تمهيد:
لما كان التعامل على الأوراق المالية غير المقيدة بالبورصة لا تسري عليه قواعد الحوكمة أو الالتزام بتقديم القوائم المالية الدورية أو السنوية أو الإفصاح عن الأحداث الجوهرية أو غيرها من الإفصاحات المطبقة على الأوراق المقيدة بجداول البورصة وفقاً لقواعد قيد وشطب الأوراق المالية المقيدة بالبورصة، فإن النظم والإجراءات المنصوص عليها في هذه القواعد جاءت لتنظيم وتيسير التعامل وإثبات نقل الملكية والاعلان عنها للأوراق المالية غير المقيدة باستخدام تقنيات النظام الآلي بالبورصة.
كذلك فإن الضوابط الخاصة بالتعامل على الأوراق المالية المقيدة لا تسري على الأوراق المالية غير المقيدة ولا يتم احتساب سعر إقفال أو فتح لأي ورقة مالية ولا يتم وضع حدود سعرية للتعامل، كما لا يتم احتساب مؤشرات لأسعارها، لذلك، فإن الحماية المقررة للمتعاملين في الأوراق المالية المقيدة غير متاحة بالنسبة للأوراق المالية غير المقيدة سواء التي يتم تداولها وفق نظام القبول الآلي للأوامر أو إثبات نقل ملكيتها وفقاً نظام نقل الملكية.

مادة (1) نظم التعامل على الأوراق المالية غير المقيدة وإجراءات نقل ملكيتها:
يتم تنفيذ عمليات التعامل على الأوراق المالية غير المقيدة بجداول البورصة المصرية وإجراءات نقل ملكيتها وفقاً لإحدى نظم التعامل وإجراءات نقل الملكية التالية: -
الأولى: نظام نقل الملكية: ويتم من خلالها إثبات نقل ملكية الأوراق المالية والاعلان عنها وذلك للأوراق المالية غير المقيدة بخلاف المشار اليها بالبند التالي.
الثانية: نظام القبول الآلي للأوامر: ويتم من خلالها التعامل وإجراء نقل الملكية والاعلان عنها للأوراق المالية غير المقيدة التي توافق إدارة البورصة على التعامل عليها وفقاً لهذا النظام وفقاً للقواعد التي يضعها مجلس إدارة البورصة وذلك للأوراق المالية التي تم شطب قيدها من جداول البورصة المصرية والمودعة بنظام الايداع والقيد المركزي للأوراق المالية.
ويتم تنفيذ العمليات السابقة وفقاً للإجراءات الواردة بهذه القواعد.

مادة (2): نظام نقل الملكية:
1. يتم من خلال هذا النظام إثبات نقل ملكية الأوراق المالية غير المقيدة التي يتم الاتفاق بين أطرافها علي نقل ملكيتها، وذلك وفقاً لما يلي:
2. تلتزم شركات الوساطة في الأوراق المالية بإخطار البورصة بالعمليات المطلوب تنفيذها لنقل ملكية الأوراق المالية غير المقيدة بها وذلك من خلال النظم والآليات المخصصة لذلك من داخل مقرات تلك الشركات الأعضاء بالبورصة او على النموذج المعد لذلك وذلك خلال شهر على الأكثر من تاريخ تحرير الأوامر، على أن يرفق بهذا الإخطار صورة من أوامر البيع والشراء لغير الأوراق المالية المودعة مركزياً.
وفى حال مرور أكثر من شهر على تاريخ تحرير أمر البيع، فعلى شركة الوساطة تقديم إقرار بما يفيد أن أمر البيع ما زال سارياً أو تقديم ذات أمر البيع موقع عليه من العميل البائع بأنه مازال سارياً وبشرط ألا يكون قد مضى على توقيعه الجديد شهر، أو تقديم أمر بيع جديد لم يمض على تحريره أسبوع.
3. تقوم البورصة بإثبات نقل ملكية الأوراق المالية والإعلان عنها بالوسائل المعدة لذلك بعد قيام شركة الوساطة في الأوراق المالية بالتأكد من وجود الورقة المالية محل الأمر في حيازة البائع او مودعه باسمه في نظام الإيداع المركزي وقدرة المشترى على الوفاء بالثمن وعدم وجود قيود قانونية على تداول الورقة المالية واستيفاء كافة المستندات الدالة على اتباع تلك القيود متى وجدت باعتبار ان شركة الوساطة في الأوراق المالية ضامنه لسلامة العملية التي تتم بواسطتها، وتحرر البورصة لصاحب الشأن ما يفيد انتقال ملكية الأوراق المالية.
4. يتم عرض أي عملية أو مجموعة عمليات مرتبطة معا تبلغ قيمتها ستون مليون جنيه فأكثر على لجنة العمليات بالبورصة قبل إثبات نقل ملكيتها والاعلان عنها، مع إخطار الهيئة والحصول على عدم ممانعة منها قبل اتمام تنفيذ تلك العمليات. (2)
5. على إدارة البورصة إخطار الجهة مصدرة الورقة المالية خلال ثلاثة أيام من تاريخ نقل ملكية الأوراق المالية.
وتضع البورصة النظام الآلي اللازم لتشغيل هذا النظام وتمكين المتعاملين وشركات الوساطة من الاستعلام عن البيانات ذات العلاقة.

مادة (3): إجراءات التعامل وفقاً لآلية نقل الملكية:
1. تكون فترة التعامل من خلال هذا النظام يومياً وتحدد البورصة ساعات العمل التي يتم خلالها تنفيذ نقل ملكية الأوراق المالية غير المقيدة والإعلان عن ذلك من خلال شاشات ادخال للعمليات يقوم بها موظفي البورصة او شركات الوساطة في الأوراق المالية، وبمراعاة وجود شاشة خاصة بالمشرف على الادخال للمراجعة.
2. لا تطبق حدود سعرية ولا يتم حساب أسعار إقفال أو فتح لتلك الأوراق المالية، كما لا يتم احتساب مؤشرات لأسعارها.
3. يتم التعامل على السندات بذات إجراءات التعامل على الأسهم بدون أي اختلاف في بيانات الأوامر.
4. يتم اجراء عمليات المقاصة والتسوية للعمليات التي يتم تنفيذها وذلك بالنسبة للأوراق المالية غير المودعة بشركة الإيداع والقيد المركزي، وتتولي البورصة إخطار شركة الايداع والقيد المركزي للأوراق المالية بعمليات إثبات الملكية والبيع والشراء فيما يخص الأوراق المالية المودعة مركزياً آلياً لإعمال شئونها.

مادة (4): نظام القبول الآلي للأوامر:
يتم من خلاله تداول الأوراق المالية غير المقيدة والإعلان عن ذلك بالنسبة للأوراق المالية المشطوبة من جداول البورصة والمودعة بنظام الايداع والقيد المركزي للأوراق المالية والتي توافق البورصة على تداولها من خلال هذا النظام وفقاً للقواعد التي يضعها مجلس إدارة البورصة، وتعلن البورصة عن الأوراق المالية المسموح بتداولها من خلال هذا النظام.
ويتم التداول وفقاً لهذا النظام باتباع نفس قواعد الأولوية المطبقة على نظام التداول داخل المقصورة، حيث يتم إدخال الأوامر من خلال شاشات شركات السمسرة التي يتم تنفيذ العملية بواسطتها وذلك من خلال برنامج منفصل يسمي نظام خارج المقصورة (OTC).
وفي حالة إجراء أية تعديلات على بيانات أو عناصر الإصدار المسجلة للأوراق المالية التي يتم التعامل عليها توقف البورصة التعامل عليها وفقاً لهذا النظام، وذلك مالم توافق البورصة على استمرار التعامل على الأوراق المالية -وفقا للقواعد التي يضعها مجلس إدارة البورصة- وفق نظام القبول الآلي للأوامر وذلك في ضوء المبررات التي تقدمها الشركة وتقبلها البورصة. (3)
وفى حالة وقف التعامل وفقاً لهذا النظام تقوم البورصة بحذف هذه الإصدارات من قاعدة بيانات نظام القبول الآلي للأوامر قبل بداية يوم العمل التالي لعلمها بهذه التعديلات، على أن يتم الإعلان عن هذا الوقف، مع الإشارة في الإعلان إلى أن عمليات نقل الملكية لهذه الأوراق سوف يكون من خلال نظام نقل الملكية.
وتضع البورصة النظام الآلي اللازم لتشغيل ذلك النظام وتمكين المتعاملين وشركات الوساطة من الاستعلام عن البيانات والمعلومات ذات العلاقة.

مادة (5): إجراءات التعامل وفقاً لنظام القبول الآلي للأوامر:
1. على شركات الوساطة في الأوراق المالية إبلاغ عملائها بخصائص التعامل بهذا النظام والأوراق المالية المسموح التعامل عليها من خلاله، وتضمن شركات الوساطة سلامة عمليات التداول التي تجريها، ومطابقتها للقوانين واللوائح والقرارات ذات العلاقة وعلى الأخص ما يلي:
- التحقق من شخصية العميل وسند ملكيته للورقة المالية وصفته وأهليته للتصرف فيها.
- التأكد من أن التعامل يتم على أوراق مالية سليمة وعلى نحو خال من الغش والنصب أو الاحتيال أو الاستغلال أو المضاربات الوهمية.
2. على شركات الوساطة التحقق من أن أوامر العملاء الصادرة لها للتعامل على هذه الأوراق مطابقة للنموذج المعد من البورصة والذي يجب أن يتضمن بياناً بالمخاطر المرتبطة بالتعامل من خلال النظام المذكور وعلى الأخص فيما يتعلق بعدم انطباق قواعد الإفصاح المطبقة على الأوراق المالية المقيدة بجداول البورصة.
3. تكون مواعيد التعامل وفقاً لهذا النظام طبقاً للتوقيتات التي يصدر بها قرار من البورصة وتعتمده الهيئة.
4. لا تطبق حدود سعرية ولا يتم حساب أسعار إقفال أو فتح لتلك الأوراق المالية، كما لا يتم احتساب مؤشرات لأسعارها.
5. تكون تسوية التعاملات التي تتم من خلال هذا النظام في اليوم الثالث من إجراء التعامل T+3.
6. تلتزم الشركات التي يتم التعامل على أوراقها وفق نظام الأوامر، وشركة الإيداع والقيد المركزي بإخطار البورصة فوراً بأية قرارات يترتب عليها تعديل في بيانات الإصدارات التي يتم التعامل عليها وفقا لنظام القبول الآلي للأوامر، وبتاريخ إجراء هذه التعديلات.
7. يتم اجراء عمليات المقاصة والتسوية بذات الإجراءات المتبعة للأوراق المالية المقيدة بالبورصة وذلك من خلال شركة الإيداع والقيد المركزي.

مادة (6): التحقق من استيفاء كافة المتطلبات اللازمة لنقل ملكية الأوراق المالية غير المقيدة:
على البورصة قبل الاعلان عن تنفيذ العمليات سواء وفقاً لنظام نقل الملكية أو نظام القبول الآلي للأوامر التحقق من استيفاء متطلبات نقل الملكية المرتبطة بالأوراق المالية الخاصة بأنشطة معينة أو بمناطق جغرافية معينة وفقاً للتشريعات المنظمة لهذه الأنشطة أو المناطق.
وعلى البورصة مراعاة ما يتم إخطارها به من قرارات أو أحكام قضائية تمنع أشخاص طبيعيين أو أشخاص اعتبارية من التصرف أو التعامل في أوراق مالية مملوكة لهم.

مادة (7): التحقق من سداد مقابل عمليات التداول ونقل ملكية الأوراق المالية غير المقيدة: (4)
تلتزم كافة شركات الوساطة في الأوراق المالية بالتعامل مع عملائها من خلال حساب بأحد البنوك الخاضعة لإشراف البنك المركزي المصري إذا زادت قيمة العملية على مائة ألف جنيه، وأن يكون التعامل مع العملاء من خارج البلاد عن طريق حساب بأحد البنوك المشار إليها أياً كانت قيمة العملية.
ويجب على شركات الوساطة في الأوراق المالية عند تنفيذ العمليات التي يكون طرفيها عملاء بالشركة التأكد من قيام العميل المشترى بإيداع قيمة مشترياته من الأوراق المالية بحساب الشركة بمراعاة الفقرة السابقة.
ويجوز للمشتري إثبات إيداع قيمة التعامل في حساب البائع بأحد البنوك خلال الشهرين السابقين على الأكثر من تاريخ تقديم طلب تنفيذ العمليات.
وباستثناء عمليات نقل ملكية الأوراق المالية بين الأزواج والأصول والفروع من الأشخاص الطبيعيين، يجوز لشركات الوساطة وتحت مسئوليتها قبول المخالصات -الصادرة بما يفيد سداد المشتري لقيمة الأوراق المالية – أو ما في حكمها أو ما يفيد إبراء ذمة المشترين على أن تلتزم الشركة بالحصول على عدم ممانعة من الهيئة على تنفيذ العملية في ضوء المستندات المقدمة من الشركة وعلى مسئوليتها.
وتلتزم شركة الوساطة في الأوراق المالية بإعداد ملف لديها تدون فيه الحالات السابق الإشارة اليها بشكل منتظم.
وللهيئة الموافقة للمشتري على التنفيذ بفترة زمنية أطول من مدة الشهرين المشار إليها بهذه المادة في حال تقديمه لمستندات بنكية مؤيدة لسداد قيمة الأوراق المالية المشتراة.

مادة (8): الإفصاح عن البيانات الخاصة بعمليات التداول على الأوراق المالية غير المقيدة
تتولى البورصة نشر البيانات الخاصة بعمليات التنفيذ ونقل الملكية على الأوراق المالية غير المقيدة وفقاً لما يلي: -
1. نشر البيانات الخاصة بعدد العمليات والكمية والقيمة ونوع الأوراق المالية وذلك لجميع العمليات المنفذة على الأوراق المالية غير المقيدة بدون حساب متوسط للسعر وحد أعلي وأدني للسعر الذي يتم عليه التداول، وذلك في النشرة اليومية.
2. نشر البيانات المشار اليها بالبند السابق في النشرة الشهرية.
3. إتاحة كافة البيانات الخاصة بتلك العمليات الكترونيا للهيئة في يوم تنفيذها.
4. ارسال بيانات العمليات الخاصة بالأوراق المالية المودعة مركزياً اليا إلى شركة المقاصة في يوم تنفيذها.

مادة (9): حالات تنفيذ عمليات نقل ملكية الأسهم وفقاً لاتفاقيات المساهمين بالشركات الناشئة (5)
في حالة قيام الشركات والجهات التي تمارس نشاط رأس المال المخاطر بالاستثمار في شركات ناشئة من خلال أدوات التمويل القابلة للتحول إلى ملكية أسهم (Convertible Instruments) والتي قد ينشأ عنها توقيع اتفاقيات مع مساهمي الشركات الناشئة ويترتب عليها إجراء عمليات نقل ملكية لأسهم تلك الشركات بعد فترة محددة وفقاً للاتفاق المبرم بين الأطراف، يجوز لشركة الإيداع والقيد المركزي للأوراق المالية أن تبرم اتفاقاً باعتبارها أمين التنفيذ (Escrow Agent) وذلك لضمان تنفيذ عمليات نقل الملكية بالبورصة.
وتضع الهيئة الشروط والمتطلبات اللازمة لإجراء عمليات نقل الملكية المشار إليها بالفقرة الأولى من هذه المادة.
وتُستثنى -بعد الحصول على موافقة الهيئة- عمليات نقل الملكية المشار إليها من شرط تقديم المستند الدال على إيداع قيمة العمليات بأحد البنوك الخاضعة لرقابة البنك المركزي المصري.

مادة (10): (6)
على شركة الإيداع والقيد المركزي للأوراق المالية إخطار البورصة المصرية بالعمليات التي تتم وفقاً لأحكام المادتين (37 و38) من قانون الإيداع والقيد المركزي للأوراق والأدوات المالية، وتقوم البورصة المصرية بقيد تلك العمليات لديها وإخطار كل من الهيئة والشركة بما يفيد إثبات نقل الملكية ونسب توزيع الأسهم على أعضاء الإيداع المركزي.

مادة (11): نظام نقل الملكية تنفيذاً للأحكام القضائية والتحكيمية وغيرها من السندات التنفيذية المتضمنة إلزاماً ببيع أو شراء الأوراق المالية أو إثبات نقل ملكيتها. (7)
يتم من خلال هذا النظام نقل ملكية الأوراق المالية المودعة مركزياً وغير المقيدة بالبورصة، وذلك بناءً على أحكام قضائية أو تحكيمية نهائية وغيرها من السندات التنفيذية المتضمنة إلزاماً ببيع أو شراء الأوراق المالية أو إثبات نقل ملكيتها.
ويُقدم طلب تنفيذ الأحكام وغيرها من السندات التنفيذية من ذوي الشأن إلى شركة الإيداع والقيد المركزي للأوراق المالية على النموذج المعد منها في هذا الشأن، مرفقاً به المستندات الآتية:
1- الحكم القضائي أو التحكيمي مشمولاً بالصيغة التنفيذية أو غير ذلك من السندات التنفيذية الأخرى، بحسب الأحوال.
2- ما يفيد إعلان المحكوم ضده إعلاناً صحيحاً وفقاً للأوضاع المقررة قانوناً.
3- ما يفيد إيداع قيمة الأوراق المالية محل التنفيذ بحساب شركة السمسرة في الأوراق المالية، وذلك في الحالات التي تتطلب سداد نقدي ووفقاً لمقتضى السند التنفيذي.
4- موافقة الجهات المختصة في حال وجود أي اشتراطات تتطلب الحصول على تلك الموافقة لنقل ملكية الأوراق المالية.
5- صورة بطاقة الرقم القومي للعميل الصادر لصالحه الحكم حال كونه مصرياً أو جواز السفر إذا كان أجنبياً أو السجل التجاري بالنسبة للشركات أو سند الإنشاء لغير الشركات.
6- توقيع إقرار من صاحب الشأن يتضمن صحة المستندات المقدمة، وأن السند التنفيذي لم يتم إلغاؤه وليس محلاً لإشكال في التنفيذ ما لم يكن قد تم رفضه.

وتقوم شركة الإيداع والقيد المركزي بعد التحقق من استيفاء الاشتراطات المشار إليها بالفقرة السابقة، بما يلي:
1- إخطار البورصة المصرية بموضوع نقل الملكية للإفادة خلال أسبوع على الأكثر عما إذا كان هناك موانع من إجراء نقل الملكية من عدمه.
2- نقل ملكية الأوراق المالية بين حسابات الأطراف المعنية لدى أمناء الحفظ، وفقاً لما قضى به السند التنفيذي.
3- تحويل قيمة الأوراق المالية إلى الحساب البنكي للطرف المستحق، وفقاً للبيانات المُبلغة إلى شركة الإيداع والقيد المركزي بناءً على قرار مجلس إدارة الهيئة رقم 61 لسنة 2017 المشار إليه، مع إخطار أمين الحفظ المعني بذلك التحويل فور إجرائه على أن يقوم أمين الحفظ بإبلاغ العميل بذلك خلال خمسة أيام عمل من تاريخ إخطاره.
4- إتمام عملية التسوية وفقاً للنظم الفنية المعمول بها لدى شركة الإيداع والقيد المركزي.

وتلتزم شركة الإيداع والقيد المركزي بتوثيق جميع العمليات المنفذة وفقاً لهذه المادة والاحتفاظ بالمستندات الدالة على ذلك، وإخطار الهيئة بالعملية فور تمام التسوية.

---
